"use strict";
window.ObsMissionDetails={render(i,brief=false){const m=i.missionDetails||{},b=i.selectedBlueprint||{},p=i.profile||{},tier=i.recipe?.tiers?.[0],e=escapeText;
 const row=(label,value)=>`<div><dt>${e(label)}</dt><dd>${e(value??'—')}</dd></div>`;
 const facts=[['Auftraggeber',m.contractor],['System',(m.systems||[]).join(' · ')],['Status',(m.active?'Aktiv':'Event / inaktiv')+' · '+(m.illegal?'Illegal':'Legal')],['Mindestrang',m.minStanding],['Voraussetzungen',(m.prerequisites||[]).join(' · ')||'Keine weiteren Angaben'],['Zeitlimit',m.timeToCompleteMinutes==null?'—':m.timeToCompleteMinutes+' Min'],['Item-Chance · Basis',m.combinedChancePercent==null?'Nicht eindeutig angegeben':m.combinedChancePercent+' % · '+(m.trigger==='accept'?'Bei Annahme':'Bei Abschluss')],['Prämie',m.rewardUEC==null?'—':Number(m.rewardUEC).toLocaleString('de-DE')+' aUEC']];
 const instance=m.logInstance||{},archiveFacts=[['Auftragsstatus',({Complete:'Erfolgreich abgeschlossen',accepted:'Angenommen',Abandon:'Abgebrochen',Fail:'Fehlgeschlagen'})[instance.status]||instance.status||'Nicht angegeben'],['Ziel',instance.target||'Unbekannt'],['Einsatzort',instance.location||'Unbekannt'],['Abgeschlossen am',instance.endedAt?new Date(instance.endedAt).toLocaleString('de-DE'):'—']];
 if(brief)return `<article class="obs-mission-dossier obs-brief"><section><h2>Auftragsbeschreibung</h2><p class="obs-full-description">${e(i.description||'Keine Beschreibung vorhanden.')}</p></section>${m.logInstance?`<section><h2>Absolvierter / archivierter Auftrag</h2><dl>${archiveFacts.map(([k,v])=>row(k,v)).join('')}</dl></section>`:''}<section><h2>Voraussetzungen</h2><dl>${facts.filter(([label])=>['Mindestrang','Voraussetzungen'].includes(label)).map(([k,v])=>row(k,v)).join('')}</dl></section></article>`;
 const image=settings.showImage&&(i.images||[]).find(x=>x.original_url?.startsWith('/media/'));
 const technique=[['Bauplan',b.name],['Hersteller',p.manufacturer||b.manufacturer],['Typ',[p.itemType,p.attachSubType].filter(Boolean).join(' / ')||b.subcategory||b.category],['Größe',b.size],['Fertigungszeit',tier?.craftTimeSeconds==null?'Unbekannt':tier.craftTimeSeconds+' Sekunden']];
 const materials=tier?.slots?.length?tier.slots.map(s=>`<li><strong>${e(s.name||'Material')}</strong>: ${(s.options||[]).map(o=>`${e(o.name||'Unbekannt')} · ${e(o.quantity??'—')}${o.minQuality?' · Mindestqualität '+e(o.minQuality):''}`).join(' / ')}</li>`).join(''):'<li>Kein eindeutig zugeordnetes Rezept vorhanden.</li>';
 return `<article class="obs-mission-dossier"><div class="obs-blueprint-hero">${image?`<img src="${e(image.original_url)}" alt="${e(b.name)}" data-image-list="${e(JSON.stringify((i.images||[]).map(x=>x.original_url||x.thumbnail_url).filter(x=>x?.startsWith('/media/'))))}"/>`:'<span>Kein zugeordnetes Bild verfügbar</span>'}<div><small>AUSGEWÄHLTER BAUPLAN</small><h2>${e(b.name)}</h2><p>${e(b.category||'')} · ${e(b.manufacturer||'')}</p></div></div><section><h2>Auftragsbeschreibung</h2><p class="obs-full-description">${e(i.description)}</p></section><section><h2>Auftrag im Überblick</h2><dl>${facts.map(([k,v])=>row(k,v)).join('')}</dl></section><section><h2>Technik und Herstellung · ${e(b.name)}</h2><p class="obs-full-description obs-tech-columns">${e(String(b.description||'Keine zusätzlichen Angaben zu Technik und Herstellung.').replace(/\\n/g,'\n').replace(/<\/?EM\d+>/gi,'').replace(/^#\s*/gm,'').trim())}</p><dl>${technique.map(([k,v])=>row(k,v)).join('')}</dl></section><section><h2>Materialien / Bauplanrezept</h2><ul>${materials}</ul></section></article>`;
}};
